// @generated by nextjs-engine global error handling — do not edit.
"use client";
import { useEffect } from "react";
import { reportEngineError } from "../src/engine/errors/engineErrorReporter";

type EngineGlobalErrorProps = {
	error: Error & { digest?: string };
	unstable_retry: () => void;
};

export default function EngineGlobalError({ error, unstable_retry }: EngineGlobalErrorProps) {
	useEffect(() => {
		reportEngineError(error, {
			code: "NECORE4002",
			source: "next-global-error",
			route: window.location.pathname,
			digest: error.digest,
			includeStack: process.env.NODE_ENV === "development",
		});
	}, [error]);

	return (
		<html lang="en">
			<body style={{ minHeight: "100vh", margin: 0, display: "grid", placeContent: "center", padding: "2rem", fontFamily: "system-ui, sans-serif" }}>
				<main role="alert">
					<h1>The application encountered an error.</h1>
					<p>Try again to reload the affected application tree.</p>
					{process.env.NODE_ENV === "development" ? <pre style={{ maxWidth: "min(80vw, 900px)", whiteSpace: "pre-wrap", overflowWrap: "anywhere" }}>{error.message}</pre> : <p>Error reference: {error.digest || "unavailable"}</p>}
					<button type="button" onClick={unstable_retry} style={{ padding: "0.6rem 1rem", cursor: "pointer" }}>Try again</button>
				</main>
			</body>
		</html>
	);
}
